app_css:
.tool-app-quotecraft { color: #1e1b4b; max-width: 860px; }
.tool-app-quotecraft .qc-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 10px; margin: 12px 0; }
.tool-app-quotecraft label { display: flex; flex-direction: column; font-size: 12px; font-weight: 600; gap: 4px; }
.tool-app-quotecraft input[type="text"], .tool-app-quotecraft input[type="number"], .tool-app-quotecraft input[type="date"], .tool-app-quotecraft textarea { border: 1px solid #c7d2fe; border-radius: 8px; padding: 8px 10px; font-size: 14px; width: 100%; box-sizing: border-box; }
.tool-app-quotecraft .qc-table { width: 100%; border-collapse: collapse; margin: 8px 0; }
.tool-app-quotecraft .qc-table th { text-align: left; font-size: 12px; color: #4c4a8a; padding: 6px; }
.tool-app-quotecraft .qc-table td { padding: 4px; border-top: 1px solid #e0e7ff; }
.tool-app-quotecraft .qc-qty, .tool-app-quotecraft .qc-price { max-width: 90px; }
.tool-app-quotecraft .qc-linetotal { font-weight: 700; white-space: nowrap; }
.tool-app-quotecraft .qc-remove { background: none; border: none; color: #b91c1c; font-size: 20px; cursor: pointer; }
.tool-app-quotecraft .qc-btn { background: #4F46E5; color: #fff; border: none; border-radius: 10px; padding: 10px 18px; font-size: 14px; font-weight: 700; cursor: pointer; }
.tool-app-quotecraft .qc-btn:hover { background: #4338ca; }
.tool-app-quotecraft .qc-btn-ghost { background: #eef2ff; color: #4F46E5; }
.tool-app-quotecraft .qc-btn-ghost:hover { background: #e0e7ff; }
.tool-app-quotecraft .qc-totals { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin: 14px 0; align-items: end; }
.tool-app-quotecraft .qc-totals > div { display: flex; justify-content: space-between; align-items: center; }
.tool-app-quotecraft .qc-grand { font-size: 20px; background: #eef2ff; border-radius: 10px; padding: 10px 14px; grid-column: 1 / -1; }
.tool-app-quotecraft .qc-notes { margin: 10px 0; }
.tool-app-quotecraft .qc-actions { display: flex; gap: 10px; margin: 14px 0; flex-wrap: wrap; }
.tool-app-quotecraft .qc-saved { list-style: none; padding: 0; margin: 8px 0; }
.tool-app-quotecraft .qc-saved li { display: flex; justify-content: space-between; align-items: center; background: #f5f7ff; border-radius: 8px; padding: 8px 12px; margin-bottom: 6px; font-size: 14px; }
.tool-app-quotecraft .qc-saved button.qc-load { background: none; border: none; color: #4F46E5; font-weight: 700; cursor: pointer; text-align: left; }
.tool-app-quotecraft .qc-saved button.qc-del { background: none; border: none; color: #b91c1c; cursor: pointer; font-size: 18px; }
.tool-app-quotecraft .tool-print-doc { display: none; }
@media print {
  .tool-app-quotecraft .qc-screen { display: none !important; }
  .tool-app-quotecraft .tool-print-doc { display: block !important; color: #000; }
  .tool-app-quotecraft .tool-print-doc table { width: 100%; border-collapse: collapse; margin: 12px 0; }
  .tool-app-quotecraft .tool-print-doc th, .tool-app-quotecraft .tool-print-doc td { border: 1px solid #999; padding: 6px; text-align: left; font-size: 13px; }
}

app_js:
(function () {
  'use strict';
  function $(id) { return document.getElementById(id); }
  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function money(n) { n = parseFloat(n); return '$' + (isFinite(n) ? n : 0).toFixed(2); }
  var root = $('toolAppRoot');
  var linesBody = $('qc-lines');
  var LS_KEY = 'toolapp-quotecraft-quotes';
  function newNumber() { return 'QC-2026-' + Math.floor(1000 + Math.random() * 9000); }
  function addLine(desc, qty, price) {
    var tr = document.createElement('tr');
    tr.className = 'qc-line';
    tr.innerHTML =
      '<td><input type="text" class="qc-desc" placeholder="Service or item" value="' + esc(desc) + '"></td>' +
      '<td><input type="number" class="qc-qty" min="0" step="1" value="' + (qty == null ? 1 : qty) + '"></td>' +
      '<td><input type="number" class="qc-price" min="0" step="0.01" value="' + (price == null ? 0 : price) + '"></td>' +
      '<td class="qc-linetotal">$0.00</td>' +
      '<td><button type="button" class="qc-remove" aria-label="Remove line">×</button></td>';
    linesBody.appendChild(tr);
    recalc();
  }
  function readLines() {
    var out = [];
    var rows = linesBody.querySelectorAll('tr.qc-line');
    for (var i = 0; i < rows.length; i++) {
      out.push({
        d: rows[i].querySelector('.qc-desc').value,
        q: parseFloat(rows[i].querySelector('.qc-qty').value) || 0,
        p: parseFloat(rows[i].querySelector('.qc-price').value) || 0
      });
    }
    return out;
  }
  function totals() {
    var lines = readLines();
    var sub = 0, i;
    for (i = 0; i < lines.length; i++) sub += lines[i].q * lines[i].p;
    var disc = Math.min(100, Math.max(0, parseFloat($('qc-discount').value) || 0));
    var tax = Math.min(100, Math.max(0, parseFloat($('qc-tax').value) || 0));
    return { lines: lines, sub: sub, disc: disc, tax: tax, total: sub * (1 - disc / 100) * (1 + tax / 100) };
  }
  function recalc() {
    var t = totals();
    var rows = linesBody.querySelectorAll('tr.qc-line');
    for (var i = 0; i < rows.length; i++) {
      rows[i].querySelector('.qc-linetotal').textContent = money(t.lines[i].q * t.lines[i].p);
    }
    $('qc-subtotal').textContent = money(t.sub);
    $('qc-total').textContent = money(t.total);
    renderPrintDoc(t);
  }
  function renderPrintDoc(t) {
    var rowsHtml = '';
    for (var i = 0; i < t.lines.length; i++) {
      var l = t.lines[i];
      rowsHtml += '<tr><td>' + esc(l.d) + '</td><td>' + l.q + '</td><td>' + money(l.p) + '</td><td>' + money(l.q * l.p) + '</td></tr>';
    }
    var notesHtml = $('qc-notes').value
      ? '<p><strong>Notes:</strong><br>' + esc($('qc-notes').value).replace(/\n/g, '<br>') + '</p>' : '';
    $('qc-printdoc').innerHTML =
      '<h1>' + esc($('qc-biz').value || 'Quote') + '</h1>' +
      '<p><strong>Quote:</strong> ' + esc($('qc-number').value) + '<br>' +
      '<strong>Date:</strong> ' + esc($('qc-date').value) + '<br>' +
      '<strong>Valid until:</strong> ' + esc($('qc-valid').value) + '<br>' +
      '<strong>Prepared for:</strong> ' + esc($('qc-client').value) + '</p>' +
      '<table><thead><tr><th>Description</th><th>Qty</th><th>Unit price</th><th>Line total</th></tr></thead>' +
      '<tbody>' + rowsHtml + '</tbody></table>' +
      '<p><strong>Subtotal:</strong> ' + money(t.sub) + '<br>' +
      '<strong>Discount:</strong> ' + t.disc + '%<br>' +
      '<strong>Tax:</strong> ' + t.tax + '%</p>' +
      '<h2>Total: ' + money(t.total) + '</h2>' + notesHtml;
  }
  function getQuotes() {
    try { return JSON.parse(localStorage.getItem(LS_KEY)) || []; } catch (e) { return []; }
  }
  function setQuotes(q) {
    try { localStorage.setItem(LS_KEY, JSON.stringify(q)); } catch (e) {}
  }
  function saveQuote() {
    var t = totals();
    var q = getQuotes();
    q.unshift({
      number: $('qc-number').value, biz: $('qc-biz').value, client: $('qc-client').value,
      date: $('qc-date').value, valid: $('qc-valid').value, disc: t.disc, tax: t.tax,
      notes: $('qc-notes').value, lines: t.lines, total: t.total,
      savedAt: new Date().toISOString()
    });
    setQuotes(q.slice(0, 50));
    renderSaved();
  }
  function renderSaved() {
    var q = getQuotes();
    var ul = $('qc-saved');
    ul.innerHTML = '';
    if (!q.length) {
      var li = document.createElement('li');
      li.textContent = 'No saved quotes yet.';
      ul.appendChild(li);
      return;
    }
    q.forEach(function (item, idx) {
      var li = document.createElement('li');
      var load = document.createElement('button');
      load.type = 'button';
      load.className = 'qc-load';
      load.setAttribute('data-idx', idx);
      load.textContent = item.number + ' — ' + (item.client || 'No client') + ' — ' + money(item.total);
      var del = document.createElement('button');
      del.type = 'button';
      del.className = 'qc-del';
      del.setAttribute('data-idx', idx);
      del.setAttribute('aria-label', 'Delete quote');
      del.textContent = '×';
      li.appendChild(load);
      li.appendChild(del);
      ul.appendChild(li);
    });
  }
  function loadQuote(idx) {
    var item = getQuotes()[idx];
    if (!item) return;
    $('qc-number').value = item.number;
    $('qc-biz').value = item.biz || '';
    $('qc-client').value = item.client || '';
    $('qc-date').value = item.date || '';
    $('qc-valid').value = item.valid || '';
    $('qc-discount').value = item.disc || 0;
    $('qc-tax').value = item.tax || 0;
    $('qc-notes').value = item.notes || '';
    linesBody.innerHTML = '';
    (item.lines || []).forEach(function (l) { addLine(l.d, l.q, l.p); });
    if (!(item.lines || []).length) addLine('', 1, 0);
    recalc();
  }
  root.addEventListener('input', function () { recalc(); });
  root.addEventListener('click', function (e) {
    var t = e.target;
    if (t.id === 'qc-addline') { addLine('', 1, 0); return; }
    if (t.id === 'qc-print') { recalc(); window.print(); return; }
    if (t.id === 'qc-save') { saveQuote(); return; }
    if (t.classList && t.classList.contains('qc-remove')) { t.closest('tr').remove(); recalc(); return; }
    if (t.classList && t.classList.contains('qc-load')) { loadQuote(parseInt(t.getAttribute('data-idx'), 10)); return; }
    if (t.classList && t.classList.contains('qc-del')) {
      var q = getQuotes();
      q.splice(parseInt(t.getAttribute('data-idx'), 10), 1);
      setQuotes(q);
      renderSaved();
    }
  });
  (function init() {
    $('qc-number').value = newNumber();
    var today = new Date();
    $('qc-date').value = today.toISOString().slice(0, 10);
    $('qc-valid').value = new Date(today.getTime() + 30 * 864e5).toISOString().slice(0, 10);
    addLine('Service', 1, 0);
    addLine('', 1, 0);
    renderSaved();
    recalc();
  })();
})();
